// Servidor (Node.js + Express)
app.post('/api/pedidos', autenticar, async (req, res) => {
  const producto = await productos.buscar(req.body.productoId);
  const total = producto.precio * req.body.cantidad;
  const pedido = await pedidos.crear(req.usuario.id, producto.id, total);
  res.status(201).json(pedido);
});

